package io.github.beboweb.shizukuinputtester;
import android.app.Activity; import android.os.Bundle; import android.os.IBinder; import android.content.ComponentName; import android.content.ServiceConnection; import android.view.InputDevice; import android.widget.*; import rikka.shizuku.Shizuku;
public class MainActivity extends Activity {
 TextView status,out; EditText x,y; IInputService svc; final int REQ=71;
 Shizuku.OnRequestPermissionResultListener perm=(code,result)->{if(code==REQ&&result==0)bind();else status.setText("Shizuku permission denied");};
 Shizuku.OnBinderReceivedListener received=()->status.setText("Shizuku connected");
 ServiceConnection conn=new ServiceConnection(){public void onServiceConnected(ComponentName n,IBinder b){svc=IInputService.Stub.asInterface(b);try{status.setText("Connected: "+svc.getIdentity());}catch(Exception e){status.setText("Identity error: "+e);}} public void onServiceDisconnected(ComponentName n){svc=null;status.setText("Service disconnected");}};
 Shizuku.UserServiceArgs args;
 public void onCreate(Bundle b){super.onCreate(b); LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(24,24,24,24); status=new TextView(this);l.addView(status); x=new EditText(this);x.setHint("X pixels");x.setInputType(2);x.setText("500");l.addView(x);y=new EditText(this);y.setHint("Y pixels");y.setInputType(2);y.setText("500");l.addView(y); Button c=new Button(this);c.setText("Connect to Shizuku");l.addView(c);Button t=new Button(this);t.setText("Inject TOUCH tap");l.addView(t);Button m=new Button(this);m.setText("Inject MOUSE tap");l.addView(m);out=new TextView(this);out.setTextIsSelectable(true);l.addView(out);TextView hint=new TextView(this);hint.setText("Coordinates are physical screen pixels. Test on a harmless target.");l.addView(hint);setContentView(l);args=new Shizuku.UserServiceArgs(new ComponentName(getPackageName(),InputUserService.class.getName())).daemon(false).processNameSuffix("input").debuggable(true).version(1);c.setOnClickListener(v->connect());t.setOnClickListener(v->inject(InputDevice.SOURCE_TOUCHSCREEN));m.setOnClickListener(v->inject(InputDevice.SOURCE_MOUSE));Shizuku.addBinderReceivedListenerSticky(received);Shizuku.addRequestPermissionResultListener(perm);status.setText(Shizuku.pingBinder()?"Shizuku available":"Waiting for Shizuku");}
 void connect(){if(!Shizuku.pingBinder()){status.setText("Shizuku not running");return;}if(Shizuku.checkSelfPermission()!=0){Shizuku.requestPermission(REQ);return;}bind();}
 void bind(){try{Shizuku.bindUserService(args,conn);status.setText("Starting Shell UserService...");}catch(Throwable e){status.setText("Bind failed: "+e);}}
 void inject(int source){if(svc==null){out.setText("Connect first");return;}try{out.setText(svc.injectTap(Integer.parseInt(x.getText().toString()),Integer.parseInt(y.getText().toString()),source));}catch(Throwable e){out.setText("ERROR: "+e);}}
 protected void onDestroy(){super.onDestroy();Shizuku.removeBinderReceivedListener(received);Shizuku.removeRequestPermissionResultListener(perm);if(svc!=null)try{Shizuku.unbindUserService(args,conn,true);}catch(Throwable ignored){}}
}